public class OrderPayloadParser {
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
        public Order() {
            this.lines = new List<Line>();
        }
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static Order parse(String body) {
        try {
            return parseInternal(body);
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Invalid payload: ' + e.getMessage());
        }
    }

    private static Decimal toDecimal(Object val) {
        if (val instanceof Decimal) {
            return (Decimal) val;
        } else if (val instanceof Integer) {
            return Decimal.valueOf((Integer) val);
        } else if (val instanceof Double) {
            return Decimal.valueOf((Double) val);
        }
        return null;
    }

    private static Order parseInternal(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank');
        }

        Object untyped;
        try {
            untyped = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON');
        }

        if (!(untyped instanceof Map<String, Object>)) {
            throw new PayloadException('Not a JSON object');
        }

        Map<String, Object> root = (Map<String, Object>) untyped;

        // number
        if (!root.containsKey('number')) {
            throw new PayloadException('Missing number');
        }
        Object numberObj = root.get('number');
        if (numberObj == null || !(numberObj instanceof String)) {
            throw new PayloadException('Invalid number');
        }
        String orderNumber = (String) numberObj;
        if (String.isBlank(orderNumber)) {
            throw new PayloadException('Blank number');
        }

        // date
        Date orderDate = null;
        if (root.containsKey('date') && root.get('date') != null) {
            Object dateObj = root.get('date');
            if (!(dateObj instanceof String)) {
                throw new PayloadException('Invalid date');
            }
            String dateStr = (String) dateObj;
            try {
                orderDate = Date.valueOf(dateStr);
            } catch (Exception e) {
                throw new PayloadException('Invalid date');
            }
        }

        // currency
        String currencyCode = null;
        if (root.containsKey('currency') && root.get('currency') != null) {
            Object currObj = root.get('currency');
            if (currObj instanceof String) {
                currencyCode = (String) currObj;
            }
        }

        // customer
        String customerEmail = null;
        if (root.containsKey('customer') && root.get('customer') != null) {
            Object custObj = root.get('customer');
            if (custObj instanceof Map<String, Object>) {
                Map<String, Object> custMap = (Map<String, Object>) custObj;
                if (custMap.containsKey('email') && custMap.get('email') != null && custMap.get('email') instanceof String) {
                    customerEmail = (String) custMap.get('email');
                }
            }
        }

        // lines
        List<Line> lines = new List<Line>();
        if (root.containsKey('lines') && root.get('lines') != null) {
            Object linesObj = root.get('lines');
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('Invalid lines');
            }
            List<Object> linesList = (List<Object>) linesObj;
            for (Object item : linesList) {
                if (item == null || !(item instanceof Map<String, Object>)) {
                    throw new PayloadException('Invalid line item');
                }
                Map<String, Object> lineMap = (Map<String, Object>) item;

                // sku
                if (!lineMap.containsKey('sku') || lineMap.get('sku') == null) {
                    throw new PayloadException('Missing sku');
                }
                Object skuObj = lineMap.get('sku');
                if (!(skuObj instanceof String) || String.isBlank((String) skuObj)) {
                    throw new PayloadException('Invalid sku');
                }
                String sku = (String) skuObj;

                // quantity
                if (!lineMap.containsKey('quantity') || lineMap.get('quantity') == null) {
                    throw new PayloadException('Missing quantity');
                }
                Decimal qtyDec = toDecimal(lineMap.get('quantity'));
                if (qtyDec == null) {
                    throw new PayloadException('Invalid quantity');
                }
                Integer quantity = qtyDec.intValue();
                if (qtyDec != Decimal.valueOf(quantity)) {
                    throw new PayloadException('Non-integer quantity');
                }
                if (quantity <= 0) {
                    throw new PayloadException('Non-positive quantity');
                }

                // unitPrice
                if (!lineMap.containsKey('unitPrice') || lineMap.get('unitPrice') == null) {
                    throw new PayloadException('Missing unitPrice');
                }
                Decimal unitPrice = toDecimal(lineMap.get('unitPrice'));
                if (unitPrice == null) {
                    throw new PayloadException('Invalid unitPrice');
                }
                if (unitPrice < 0) {
                    throw new PayloadException('Negative unitPrice');
                }

                // discount
                Decimal discount = 0;
                if (lineMap.containsKey('discount') && lineMap.get('discount') != null) {
                    Decimal discDec = toDecimal(lineMap.get('discount'));
                    if (discDec == null) {
                        throw new PayloadException('Invalid discount');
                    }
                    discount = discDec;
                }

                Decimal lineTotal = (unitPrice * Decimal.valueOf(quantity) * (Decimal.valueOf(1) - discount)).setScale(2, System.RoundingMode.HALF_UP);

                Line line = new Line();
                line.sku = sku;
                line.quantity = quantity;
                line.unitPrice = unitPrice;
                line.discount = discount;
                line.lineTotal = lineTotal;
                lines.add(line);
            }
        }

        Decimal total = Decimal.valueOf(0);
        for (Line l : lines) {
            total = total + l.lineTotal;
        }

        Order order = new Order();
        order.orderNumber = orderNumber;
        order.orderDate = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines = lines;
        order.total = total;
        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>{
            'number' => (order != null && order.orderNumber != null) ? order.orderNumber : '',
            'status' => 'RECEIVED',
            'lineCount' => (order != null && order.lines != null) ? order.lines.size() : 0,
            'total' => (order != null && order.total != null) ? order.total : Decimal.valueOf(0)
        };
        return JSON.serialize(ack);
    }
}
