@isTest
private class OpportunityWonHandlerTest {

    @isTest
    static void testBeforeInsertNewlyWonSetsNextStep() {
        Opportunity opp = new Opportunity(
            Name = 'Insert Won',
            StageName = OpportunityWonHandler.WON,
            CloseDate = Date.newInstance(2025, 7, 1)
        );
        insert opp;
        Opportunity result = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(OpportunityWonHandler.HANDOVER, result.NextStep, 'NextStep should be set for newly won insert');
    }

    @isTest
    static void testBeforeInsertNotWonDoesNothing() {
        Opportunity opp = new Opportunity(
            Name = 'Insert Not Won',
            StageName = 'Prospecting',
            CloseDate = Date.today()
        );
        insert opp;
        Opportunity result = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(null, result.NextStep, 'NextStep should stay null when not won on insert');
    }

    @isTest
    static void testBeforeUpdateToWonSetsNextStep() {
        Opportunity opp = new Opportunity(
            Name = 'Update To Won',
            StageName = 'Prospecting',
            CloseDate = Date.today()
        );
        insert opp;
        opp.StageName = OpportunityWonHandler.WON;
        update opp;
        Opportunity result = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(OpportunityWonHandler.HANDOVER, result.NextStep, 'NextStep should be set when updated to won');
    }

    @isTest
    static void testBeforeUpdateAlreadyWonDoesNotModifyNextStep() {
        Opportunity opp = new Opportunity(
            Name = 'Already Won',
            StageName = OpportunityWonHandler.WON,
            CloseDate = Date.today()
        );
        insert opp;
        opp.NextStep = 'Custom';
        opp.Name = 'Updated';
        update opp;
        Opportunity result = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals('Custom', result.NextStep, 'NextStep must not be overwritten when already won');
    }

    @isTest
    static void testAfterInsertNewlyWonCreatesTaskAndUpdatesAccount() {
        Account acc = new Account(Name = 'Related', Rating = 'Warm');
        insert acc;

        Opportunity opp = new Opportunity(
            Name = 'Won Insert',
            StageName = OpportunityWonHandler.WON,
            CloseDate = Date.newInstance(2025, 6, 15),
            AccountId = acc.Id
        );
        insert opp;

        Opportunity insertedOpp = [SELECT Id, OwnerId FROM Opportunity WHERE Id = :opp.Id];
        List<Task> tasks = [SELECT Id, Subject, WhatId, OwnerId, ActivityDate, Priority FROM Task WHERE WhatId = :opp.Id];
        System.assertEquals(1, tasks.size(), 'Exactly one task for newly won insert');
        Task t = tasks[0];
        System.assertEquals('Customer kick-off', t.Subject);
        System.assertEquals(insertedOpp.Id, t.WhatId);
        System.assertEquals(insertedOpp.OwnerId, t.OwnerId);
        System.assertEquals(Date.newInstance(2025, 6, 22), t.ActivityDate, 'ActivityDate = CloseDate + 7');
        System.assertEquals('High', t.Priority);

        acc = [SELECT Rating FROM Account WHERE Id = :acc.Id];
        System.assertEquals('Hot', acc.Rating, 'Account should become Hot');
    }

