public with sharing class LineItemDiscountHandler {
    /*
     * WHAT CHANGED / WHY:
     * PricingRules.standardDiscountFor does a SOQL query per call.
     * With up to 200 lines that blows the 100-query limit.
     * A static Map caches discounts by Product2Id so we call
     * PricingRules.standardDiscountFor(line.Product2Id) only once
     * per unique product, keeping rules in one place and staying bulk-safe.
     * Lines that already have a Discount (including 0) are untouched.
     */
    private static Map<Id, Decimal> discountCache = new Map<Id, Decimal>();

    public static void applyStandardDiscounts(List<OpportunityLineItem> lines) {
        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && line.Product2Id != null) {
                Id prodId = line.Product2Id;

                if (!discountCache.containsKey(prodId)) {
                    discountCache.put(prodId, PricingRules.standardDiscountFor(line.Product2Id));
                }

                line.Discount = discountCache.get(prodId);
            }
        }
    }
}
