public class FamilyService {
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> allIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null) {
                allIds.add(childId);
            }
            if (parentId != null) {
                allIds.add(parentId);
            }
        }
        if (allIds.isEmpty()) {
            return;
        }

        // 1. Resolve the active "Parent" relationship lookup (List Setting)
        Id parentLookupId;
        for (npe4__Relationship_Lookup__c l : [
            SELECT Id
            FROM npe4__Relationship_Lookup__c
            WHERE Name = 'Parent'
              AND npe4__Active__c = true
            LIMIT 1
        ]) {
            parentLookupId = l.Id;
        }
        if (parentLookupId == null) {
            return;
        }

        // 2. Check for any existing relationship between involved contacts (either direction)
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allIds
               OR npe4__RelatedContact__c IN :allIds
        ]) {
            existingPairs.add(rel.npe4__Contact__c + ':' + rel.npe4__RelatedContact__c);
            existingPairs.add(rel.npe4__RelatedContact__c + ':' + rel.npe4__Contact__c);
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (parentId == null || childId == null || childId.equals(parentId)) {
                continue;
            }

            String pairKey = childId + ':' + parentId;
            String revKey = parentId + ':' + childId;
            if (existingPairs.contains(pairKey) || existingPairs.contains(revKey)) {
                continue;
            }

            // Insert only the child -> Parent direction.
            // With the default "List Setting" reciprocal method, NPSP creates
            // the reciprocal Parent -> Child (Son/Daughter/Child) automatically.
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = parentLookupId,
                npe4__Status__c = 'Current',
                npe4__Description__c = 'Parent'
            ));
        }

        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
